import { pipeline } from "node:stream/promises";
import mongoose from "mongoose";

function attachmentBucket() {
  return new mongoose.mongo.GridFSBucket(mongoose.connection.db, {
    bucketName: "chatAttachments",
  });
}

export async function saveAttachment(filename, file) {
  const stream = attachmentBucket().openUploadStream(filename, {
    metadata: { mimeType: file.mimetype },
  });
  await pipeline([file.buffer], stream);
}

export async function serveAttachment(req, res, next) {
  // The GridFS filenames are generated by the upload route.
  if (!/^[0-9a-f-]{36}\.[a-z0-9]+$/i.test(req.params.filename)) return next();

  try {
    const bucket = attachmentBucket();
    const [file] = await bucket.find({ filename: req.params.filename }).limit(1).toArray();
    if (!file) return next();

    const length = file.length;
    const ranges = req.range(length);
    let start = 0;
    let end = length;

    if (ranges === -1) {
      return res.set("Content-Range", `bytes */${length}`).sendStatus(416);
    }

    res.set({
      "Accept-Ranges": "bytes",
      "Content-Type": file.metadata.mimeType,
    });
    if (Array.isArray(ranges) && ranges.type === "bytes" && ranges.length === 1) {
      start = ranges[0].start;
      end = ranges[0].end + 1;
      res.status(206).set("Content-Range", `bytes ${start}-${end - 1}/${length}`);
    }
    res.set("Content-Length", String(end - start));
    if (req.method === "HEAD" || !length) return res.end();

    await pipeline(bucket.openDownloadStream(file._id, { start, end }), res);
  } catch (error) {
    if (!res.destroyed) next(error);
  }
}
